CREATE TEMP TABLE s2_out (k text PRIMARY KEY, v jsonb) ON COMMIT DROP;
CREATE TEMP TABLE s2_fx (k text PRIMARY KEY, v uuid) ON COMMIT DROP;
CREATE FUNCTION pg_temp.rec(k text, v jsonb) RETURNS void LANGUAGE sql AS $h$
  INSERT INTO pg_temp.s2_out VALUES (k, v) ON CONFLICT (k) DO UPDATE SET v = excluded.v
$h$;
CREATE FUNCTION pg_temp.f(k text) RETURNS uuid LANGUAGE sql STABLE AS $h$ SELECT v FROM pg_temp.s2_fx WHERE s2_fx.k = f.k $h$;
CREATE FUNCTION pg_temp.s(k text) RETURNS text LANGUAGE sql STABLE AS $h$ SELECT v::text FROM pg_temp.s2_fx WHERE s2_fx.k = s.k $h$;
CREATE FUNCTION pg_temp.fx(n text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $h$ SELECT md5('p4263:sync2-s2-harness:' || n)::uuid $h$;
CREATE FUNCTION pg_temp.h(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$ SELECT encode(sha256(convert_to(t, 'UTF8')), 'hex') $h$;
CREATE FUNCTION pg_temp.j(t text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $h$
BEGIN RETURN t::jsonb; EXCEPTION WHEN OTHERS THEN RETURN to_jsonb(t); END $h$;
CREATE FUNCTION pg_temp.pass(c boolean, detail text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT CASE WHEN coalesce(c, false) THEN 'PASS' ELSE 'FAIL: ' || coalesce(left(detail, 900), '-') END
$h$;
CREATE FUNCTION pg_temp.clear_claims() RETURNS void LANGUAGE plpgsql AS $h$
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);
  PERFORM set_config('request.jwt.claim.role', '', true);
END $h$;
-- One statement as an API role with the user's claims (own subtransaction); an error returns 'ERR <sqlstate> <message>'.
CREATE FUNCTION pg_temp.call_as(u uuid, q text, r text DEFAULT 'authenticated') RETURNS text LANGUAGE plpgsql AS $h$
DECLARE j jsonb;
BEGIN
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', u, 'role', r)::text, true);
    PERFORM set_config('request.jwt.claim.sub', coalesce(u::text, ''), true);
    PERFORM set_config('request.jwt.claim.role', r, true);
    EXECUTE format('SET LOCAL ROLE %I', r);
    EXECUTE q INTO j;
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN coalesce(j::text, 'null');
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM pg_temp.clear_claims();
    RETURN 'ERR ' || SQLSTATE || ' ' || left(SQLERRM, 200);
  END;
END $h$;
-- public.<fn>(args) as the fixture user; args is a format() list of %L placeholders.
CREATE FUNCTION pg_temp.call(fn text, args text, VARIADIC vals text[]) RETURNS jsonb LANGUAGE plpgsql AS $h$
DECLARE q text := 'SELECT to_jsonb(public.' || quote_ident(fn) || '(' || args || '))';
BEGIN
  q := format(q, VARIADIC vals);
  RETURN pg_temp.j(pg_temp.call_as(pg_temp.f('A'), q));
END $h$;
CREATE FUNCTION pg_temp.list(inst text, kind text, after_ uuid, lim integer) RETURNS jsonb LANGUAGE sql AS $h$
  SELECT pg_temp.call('cloud_list_install_rows', '%L::uuid, %L::uuid, %L::text, %L::uuid, %L::integer', pg_temp.s('A'), pg_temp.s(inst),
                      kind, after_::text, lim::text)
$h$;
-- the two switches, changed inside this transaction only (undone by the final RAISE)
CREATE FUNCTION pg_temp.upload(on_ boolean) RETURNS void LANGUAGE sql AS $h$
  UPDATE public.cloud_release_switches SET messages_upload = on_ WHERE id
$h$;
CREATE FUNCTION pg_temp.computer(on_ boolean) RETURNS void LANGUAGE sql AS $h$
  UPDATE public.cloud_release_switches SET one_computer = on_ WHERE id
$h$;
CREATE FUNCTION pg_temp.msgs() RETURNS bigint LANGUAGE sql AS $h$
  SELECT count(*) FROM public.cloud_deal_messages WHERE owner_user_id = pg_temp.f('A')
$h$;
CREATE FUNCTION pg_temp.live_files() RETURNS bigint LANGUAGE sql AS $h$
  SELECT count(*) FROM public.cloud_deal_files WHERE owner_user_id = pg_temp.f('A') AND removed_at IS NULL
$h$;
CREATE FUNCTION pg_temp.files_state() RETURNS jsonb LANGUAGE sql AS $h$
  SELECT jsonb_agg(jsonb_build_object('id', f.local_attachment_id, 'removed', f.removed_at IS NOT NULL, 'blob', f.blob_id IS NOT NULL,
                                      'fenced', (SELECT b.purge_requested_at IS NOT NULL FROM public.cloud_blobs b WHERE b.id = f.blob_id))
                   ORDER BY f.local_attachment_id)
    FROM public.cloud_deal_files f WHERE f.owner_user_id = pg_temp.f('A')
$h$;
-- Fingerprint of everything the fixture user has online (rows and their versions, removal and save times).
CREATE FUNCTION pg_temp.fp() RETURNS text LANGUAGE sql AS $h$
  SELECT md5(concat_ws('|',
    (SELECT string_agg(concat_ws(',', d.id, d.version, d.removed_at, d.last_synced_at, d.content_hash), ';' ORDER BY d.id)
       FROM public.cloud_deals d WHERE d.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', m.id, m.version, m.removed_at, m.content_hash), ';' ORDER BY m.id)
       FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', f.id, f.version, f.removed_at, f.blob_id), ';' ORDER BY f.id)
       FROM public.cloud_deal_files f WHERE f.owner_user_id = pg_temp.f('A')),
    (SELECT string_agg(concat_ws(',', b.id, b.uploaded_at, b.purge_requested_at), ';' ORDER BY b.id)
       FROM public.cloud_blobs b WHERE b.owner_user_id = pg_temp.f('A'))))
$h$;
CREATE FUNCTION pg_temp.dp(inst text, lid text) RETURNS text LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('source_install_id', inst, 'local_id', lid, 'content_hash', pg_temp.h(lid))::text
$h$;
-- one message row as the desktop sends it (text rows carry a thread key)
CREATE FUNCTION pg_temp.mrow(lid text, kind text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_build_object('local_id', lid, 'content_hash', pg_temp.h(lid), 'channel_kind', kind, 'hidden_from_export', false,
                            'channel', CASE WHEN kind = 'text' THEN 'sms' ELSE 'email' END, 'subject', 'Subject ' || lid,
                            'body_text', 'Body ' || lid, 'participants', '{"from": "Fixture"}'::jsonb, 'link_origin', 'link')
         || CASE WHEN kind = 'text' THEN jsonb_build_object('thread_key', 'thread-' || lid) ELSE '{}'::jsonb END
$h$;
-- one file row; parent message by local id (email), blob by its sha, or a reason it has no bytes
CREATE FUNCTION pg_temp.frow(lid text, msg text, blob_sha text, reason text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $h$
  SELECT jsonb_strip_nulls(jsonb_build_object('local_id', lid, 'content_hash', pg_temp.h(lid), 'filename', lid || '.pdf',
                            'mime_type', 'application/pdf', 'size_bytes', 10, 'not_saved_reason', reason,
                            'message_local_id', msg, 'message_channel_kind', CASE WHEN msg IS NULL THEN NULL WHEN msg LIKE '%-t' THEN 'text' ELSE 'email' END,
                            'blob_sha256', blob_sha))
$h$;


-- Fixture user A: licensed through an organization on the team plan, Keepr Cloud on (notice 1). Installs IA (active),
-- IB, IC (no deals). Deal dA (IA): party pA; messages m1 (email fx-m1), m2 (text fx-m2-t), m3 (email fx-m3); files f1
-- (m1, blob b1), f2 (m1, too large), f3 (m2, blob b2), f4 (m3, blob b1). Deal dB (IB): message mB. Written while
-- one_computer is off and messages_upload is on (both changed in this transaction only).
DO $fx$
DECLARE A uuid := pg_temp.fx('A'); O uuid := pg_temp.fx('O'); r jsonb; n int;
BEGIN
  INSERT INTO pg_temp.s2_fx SELECT k, pg_temp.fx(k) FROM unnest(ARRAY['A', 'O', 'M', 'IA', 'IB', 'IC']) k;
  SET LOCAL session_replication_role = replica;
  INSERT INTO auth.users (id, email, aud, role, instance_id, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
  VALUES (A, 'p4263-s2-' || substr(md5('s2-harness'), 1, 8) || '-a@example.test', 'authenticated', 'authenticated',
          '00000000-0000-0000-0000-000000000000', '{"provider":"email"}', '{}', now(), now());
  INSERT INTO public.users (id, email, oauth_provider, oauth_id, display_name)
  VALUES (A, 'p4263-s2-' || substr(md5('s2-harness'), 1, 8) || '-a@example.test', 'email', A::text, 'Fixture s2') ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.organizations (id, name, slug) VALUES (O, 'Fixture s2', 'p4263-s2-' || substr(md5('s2-harness'), 1, 8));
  INSERT INTO public.organization_members (id, organization_id, user_id, role, license_status) VALUES (pg_temp.fx('M'), O, A, 'agent', 'active');
  INSERT INTO public.organization_plans (organization_id, plan_id, feature_overrides)
  VALUES (O, (SELECT id FROM public.plans WHERE tier = 'team' ORDER BY sort_order, name LIMIT 1), '{"cloud_autosave_assignable":{"enabled":true}}');
  SET LOCAL session_replication_role = origin;
  UPDATE public.cloud_release_switches SET one_computer = false, messages_upload = true WHERE id;
  r := pg_temp.j(pg_temp.call_as(NULL, format('SELECT public.assign_member_addon(%L::uuid, %L::uuid, %L, true, NULL::timestamptz)', O, A, 'cloud_autosave'), 'service_role'));
  IF r ->> 'state' IS DISTINCT FROM 'assigned' THEN RAISE EXCEPTION 'FIXTURE assign failed: %', r; END IF;
  r := pg_temp.call('set_my_cloud_autosave', '%L::uuid, %L::boolean, %L::integer, %L::uuid', A::text, 'true', '1', NULL);
  IF r ->> 'success' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE enable failed: %', r; END IF;
  FOREACH n IN ARRAY ARRAY[1, 2] LOOP
    r := pg_temp.call('cloud_upsert_deal', '%L::uuid, %L::jsonb', A::text, pg_temp.dp(pg_temp.s((ARRAY['IA', 'IB'])[n]), 'fx-deal-' || n));
    IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE deal % failed: %', n, r; END IF;
    INSERT INTO pg_temp.s2_fx VALUES ((ARRAY['dA', 'dB'])[n], (r -> 'results' -> 0 ->> 'cloud_id')::uuid);
  END LOOP;
  r := pg_temp.call('cloud_upsert_parties', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.s('IA'), pg_temp.s('dA'),
                    jsonb_build_array(jsonb_build_object('local_id', 'fx-party', 'content_hash', pg_temp.h('fx-party')))::text);
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE party failed: %', r; END IF;
  r := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.s('IA'), pg_temp.s('dA'),
                    jsonb_build_array(pg_temp.mrow('fx-m1', 'email'), pg_temp.mrow('fx-m2-t', 'text'), pg_temp.mrow('fx-m3', 'email'))::text);
  IF (SELECT count(*) FROM jsonb_array_elements(r -> 'results') e WHERE e ->> 'status' = 'applied') <> 3 THEN RAISE EXCEPTION 'FIXTURE messages failed: %', r; END IF;
  INSERT INTO pg_temp.s2_fx SELECT u.key, (r -> 'results' -> (u.pos - 1)::int ->> 'cloud_id')::uuid FROM unnest(ARRAY['m1', 'm2', 'm3']) WITH ORDINALITY u(key, pos);
  r := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.s('IB'), pg_temp.s('dB'),
                    jsonb_build_array(pg_temp.mrow('fx-mb', 'email'))::text);
  IF r -> 'results' -> 0 ->> 'status' IS DISTINCT FROM 'applied' THEN RAISE EXCEPTION 'FIXTURE message B failed: %', r; END IF;
  INSERT INTO pg_temp.s2_fx VALUES ('mB', (r -> 'results' -> 0 ->> 'cloud_id')::uuid);
  FOREACH n IN ARRAY ARRAY[1, 2] LOOP
    r := pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', A::text, pg_temp.s('IA'),
                      pg_temp.h('fx-blob-' || n), '10', 'application/pdf');
    IF r ->> 'state' IS DISTINCT FROM 'new' THEN RAISE EXCEPTION 'FIXTURE blob % failed: %', n, r; END IF;
    INSERT INTO pg_temp.s2_fx VALUES ((ARRAY['b1', 'b2'])[n], (r ->> 'blob_id')::uuid);
  END LOOP;
  -- uploaded as cloud_confirm_blob records it (no storage object is written by this harness)
  UPDATE public.cloud_blobs SET uploaded_at = now() WHERE id IN (pg_temp.f('b1'), pg_temp.f('b2'));
  r := pg_temp.call('cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', A::text, pg_temp.s('IA'), pg_temp.s('dA'),
                    jsonb_build_array(pg_temp.frow('fx-f1', 'fx-m1', pg_temp.h('fx-blob-1'), NULL), pg_temp.frow('fx-f2', 'fx-m1', NULL, 'too_large'),
                                      pg_temp.frow('fx-f3', 'fx-m2-t', pg_temp.h('fx-blob-2'), NULL), pg_temp.frow('fx-f4', 'fx-m3', pg_temp.h('fx-blob-1'), NULL))::text);
  IF (SELECT count(*) FROM jsonb_array_elements(r -> 'results') e WHERE e ->> 'status' = 'applied') <> 4 THEN RAISE EXCEPTION 'FIXTURE files failed: %', r; END IF;
  INSERT INTO pg_temp.s2_fx SELECT u.key, (r -> 'results' -> (u.pos - 1)::int ->> 'cloud_id')::uuid FROM unnest(ARRAY['f1', 'f2', 'f3', 'f4']) WITH ORDINALITY u(key, pos);
  UPDATE public.cloud_autosave_settings SET active_install_id = NULL, active_since = NULL WHERE user_id = A;
  r := pg_temp.call('cloud_claim_install', '%L::uuid, %L::uuid, %L::boolean', A::text, pg_temp.s('IA'), 'false');
  IF r ->> 'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'FIXTURE claim failed: %', r; END IF;
END
$fx$;

CREATE FUNCTION pg_temp.c7a_messages() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(false);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), jsonb_build_array(pg_temp.mrow('c7a-off-messages', 'email'))::text);
  after := pg_temp.fp();
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), jsonb_build_array(pg_temp.mrow('c7a-on-messages', 'email'))::text);
  RETURN pg_temp.pass((rb ->> 'ok') = 'false' AND (rb ->> 'error') = 'feature_off' AND before = after AND (ra -> 'results' -> 0 ->> 'status') = 'applied',
                      jsonb_build_object('off', rb, 'on', ra, 'unchanged', before = after)::text);
END $c$;
CREATE FUNCTION pg_temp.c7a_files() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(false);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), jsonb_build_array(pg_temp.frow('c7a-off-files', NULL, NULL, 'too_large'))::text);
  after := pg_temp.fp();
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), jsonb_build_array(pg_temp.frow('c7a-on-files', NULL, NULL, 'too_large'))::text);
  RETURN pg_temp.pass((rb ->> 'ok') = 'false' AND (rb ->> 'error') = 'feature_off' AND before = after AND (ra -> 'results' -> 0 ->> 'status') = 'applied',
                      jsonb_build_object('off', rb, 'on', ra, 'unchanged', before = after)::text);
END $c$;
CREATE FUNCTION pg_temp.c7a_register() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(false);
  before := pg_temp.fp();
  rb := pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.h('c7a-off-register'), '10', NULL);
  after := pg_temp.fp();
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.h('c7a-on-register'), '10', NULL);
  RETURN pg_temp.pass((rb ->> 'ok') = 'false' AND (rb ->> 'error') = 'feature_off' AND before = after AND (ra ->> 'state') = 'new',
                      jsonb_build_object('off', rb, 'on', ra, 'unchanged', before = after)::text);
END $c$;
CREATE FUNCTION pg_temp.c7a_not_gated() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(false);
  v := jsonb_build_object(
    'confirm', pg_temp.call('cloud_confirm_blob', '%L::uuid, %L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('b1')),
    'list_message', pg_temp.list('IA', 'message', NULL, 1000),
    'list_file', pg_temp.list('IA', 'file', NULL, 1000),
    'tombstone_file', pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'file', ARRAY[pg_temp.f('f2')]::text),
    'mark_synced', pg_temp.call('cloud_mark_deal_synced', '%L::uuid, %L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA')),
    'delete_deal', pg_temp.call('cloud_delete_deal', '%L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('dA')));
  RETURN pg_temp.pass(v::text NOT LIKE '%feature_off%' AND v::text NOT LIKE '%ERR %'
                      AND (v -> 'confirm' ->> 'state') = 'uploaded' AND (v -> 'list_message' ->> 'ok') = 'true'
                      AND jsonb_array_length(v -> 'list_message' -> 'rows') = 3 AND jsonb_array_length(v -> 'list_file' -> 'rows') = 4
                      AND (v -> 'tombstone_file' -> 'results' -> 0 ->> 'status') = 'removed'
                      AND (v -> 'mark_synced' ->> 'ok') = 'true' AND (v -> 'delete_deal' ->> 'ok') = 'true', v::text);
END $c$;
CREATE FUNCTION pg_temp.c7c_off_tombstone() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(false);
  v := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'message', ARRAY[pg_temp.f('m2')]::text);
  RETURN pg_temp.pass((v -> 'results' -> 0 ->> 'status') = 'removed'
                      AND (SELECT m.removed_at IS NOT NULL AND m.subject IS NULL AND m.body_text IS NULL AND m.participants IS NULL
                             FROM public.cloud_deal_messages m WHERE m.id = pg_temp.f('m2'))
                      AND (SELECT f.removed_at IS NOT NULL AND f.filename IS NULL AND f.blob_id IS NULL FROM public.cloud_deal_files f WHERE f.id = pg_temp.f('f3'))
                      AND (SELECT b.purge_requested_at IS NOT NULL FROM public.cloud_blobs b WHERE b.id = pg_temp.f('b2'))
                      AND pg_temp.live_files() = 3,
                      jsonb_build_object('tombstone', v, 'files', pg_temp.files_state())::text);
END $c$;
CREATE FUNCTION pg_temp.c_cascade() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'message', ARRAY[pg_temp.f('m1')]::text);
  x_n := (SELECT version FROM public.cloud_deal_files WHERE id = pg_temp.f('f1'));
  rb := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'message', ARRAY[pg_temp.f('m1')]::text);
  v := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'file', ARRAY[pg_temp.f('f1')]::text);
  RETURN pg_temp.pass(
    jsonb_array_length(ra -> 'results') = 1
    AND (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(ra -> 'results' -> 0) k) = ARRAY['cloud_id', 'status', 'version']
    AND (ra -> 'results' -> 0 ->> 'status') = 'removed'
    AND (SELECT count(*) FROM public.cloud_deal_files f WHERE f.id IN (pg_temp.f('f1'), pg_temp.f('f2'))
           AND f.removed_at IS NOT NULL AND f.filename IS NULL AND f.blob_id IS NULL) = 2
    AND (SELECT f.removed_at IS NULL AND f.blob_id = pg_temp.f('b1') FROM public.cloud_deal_files f WHERE f.id = pg_temp.f('f4'))
    AND (SELECT f.removed_at IS NULL FROM public.cloud_deal_files f WHERE f.id = pg_temp.f('f3'))
    AND (SELECT m.removed_at IS NULL FROM public.cloud_deal_messages m WHERE m.id = pg_temp.f('m3'))
    AND (SELECT b.purge_requested_at IS NULL FROM public.cloud_blobs b WHERE b.id = pg_temp.f('b1'))
    AND (rb -> 'results' -> 0 ->> 'status') = 'unchanged' AND (v -> 'results' -> 0 ->> 'status') = 'unchanged'
    AND (SELECT version FROM public.cloud_deal_files WHERE id = pg_temp.f('f1')) = x_n,
    jsonb_build_object('first', ra, 'again', rb, 'file', v, 'files', pg_temp.files_state())::text);
END $c$;
CREATE FUNCTION pg_temp.c_cascade_keeps_removed() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'file', ARRAY[pg_temp.f('f2')]::text);
  x_n := (SELECT version FROM public.cloud_deal_files WHERE id = pg_temp.f('f2'));
  rb := pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IA'), 'message', ARRAY[pg_temp.f('m1')]::text);
  RETURN pg_temp.pass((ra -> 'results' -> 0 ->> 'status') = 'removed' AND (rb -> 'results' -> 0 ->> 'status') = 'removed'
                      AND (SELECT version FROM public.cloud_deal_files WHERE id = pg_temp.f('f2')) = x_n
                      AND (SELECT f.removed_at IS NOT NULL AND f.version > 0 FROM public.cloud_deal_files f WHERE f.id = pg_temp.f('f1')),
                      jsonb_build_object('file', ra, 'message', rb, 'f2_version_before', x_n,
                                         'f2_version_after', (SELECT version FROM public.cloud_deal_files WHERE id = pg_temp.f('f2')))::text);
END $c$;
CREATE FUNCTION pg_temp.c_review_queue() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  x_n := pg_temp.msgs();
  v := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         jsonb_build_array(pg_temp.mrow('q-1', 'email') || '{"link_origin": "review_queue"}', pg_temp.mrow('q-2', 'email') || '{"link_origin": "link"}')::text);
  RETURN pg_temp.pass((v -> 'results' -> 0 ->> 'status') = 'rejected' AND (v -> 'results' -> 0 ->> 'reason') = 'review_queue_not_accepted'
                      AND (v -> 'results' -> 1 ->> 'status') = 'applied' AND pg_temp.msgs() = x_n + 1
                      AND NOT EXISTS (SELECT 1 FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A') AND m.local_message_id = 'q-1')
                      AND NOT EXISTS (SELECT 1 FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A') AND m.link_state = 'suggested'),
                      v::text);
END $c$;
CREATE FUNCTION pg_temp.c_link_state() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  v := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         jsonb_build_array(pg_temp.mrow('ls-1', 'email') || '{"match_reason": "address_missing", "link_confidence": 0.5, "link_source": "auto"}',
                           pg_temp.mrow('ls-2', 'email') || '{"match_reason": "address", "link_source": "auto"}',
                           pg_temp.mrow('ls-3', 'text') || '{"link_source": "manual"}')::text);
  RETURN pg_temp.pass((SELECT string_agg(m.local_message_id || '=' || m.link_state, ',' ORDER BY m.local_message_id)
                         FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A') AND m.local_message_id LIKE 'ls-%')
                      = 'ls-1=needs_review,ls-2=linked,ls-3=linked', v::text);
END $c$;
CREATE FUNCTION pg_temp.c_hidden() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         jsonb_build_array(pg_temp.mrow('hd-1', 'text') || '{"hidden_from_export": true}', pg_temp.mrow('hd-2', 'text'))::text);
  rb := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         jsonb_build_array(pg_temp.mrow('hd-1', 'text') || '{"hidden_from_export": true}')::text);
  RETURN pg_temp.pass((SELECT string_agg(m.local_message_id || '=' || m.hidden_from_export, ',' ORDER BY m.local_message_id)
                         FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A') AND m.local_message_id LIKE 'hd-%')
                      = 'hd-1=true,hd-2=false' AND (rb -> 'results' -> 0 ->> 'status') = 'unchanged',
                      jsonb_build_object('first', ra, 'resend', rb)::text);
END $c$;
CREATE FUNCTION pg_temp.c_caps() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         (SELECT jsonb_agg(pg_temp.mrow('cap-' || g, 'email')) FROM generate_series(1, 500) g)::text);
  rb := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'),
         (SELECT jsonb_agg(pg_temp.mrow('cap501-' || g, 'email')) FROM generate_series(1, 501) g)::text);
  v := jsonb_build_object(
    'at', pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.h('cap-at'), '52428800', NULL),
    'over', pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.h('cap-over'), '52428801', NULL));
  RETURN pg_temp.pass((ra ->> 'ok') = 'true' AND jsonb_array_length(ra -> 'results') = 500
                      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ra -> 'results') e WHERE e ->> 'status' <> 'applied')
                      AND (rb ->> 'error') = 'batch_too_large'
                      AND NOT EXISTS (SELECT 1 FROM public.cloud_deal_messages m WHERE m.owner_user_id = pg_temp.f('A') AND m.local_message_id LIKE 'cap501-%')
                      AND (v -> 'at' ->> 'state') = 'new' AND (v -> 'over' ->> 'error') = 'too_large',
                      jsonb_build_object('n500', ra ->> 'ok', 'n501', rb, 'blob', v)::text);
END $c$;
CREATE FUNCTION pg_temp.c7b_list_message() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.list('IA', 'message', NULL, 2);
  rb := pg_temp.list('IA', 'message', (ra ->> 'next_after')::uuid, 2);
  v := pg_temp.call('cloud_delete_deal', '%L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('dA'));
  x_j := pg_temp.list('IA', 'message', NULL, 1000);
  RETURN pg_temp.pass(
    jsonb_array_length(ra -> 'rows') = 2 AND (ra ->> 'next_after') = (ra -> 'rows' -> 1 ->> 'cloud_id')
    AND jsonb_array_length(rb -> 'rows') = 1 AND rb -> 'next_after' = 'null'::jsonb
    AND (ra -> 'rows' -> 0 ->> 'cloud_id')::uuid < (ra -> 'rows' -> 1 ->> 'cloud_id')::uuid
    AND (ra -> 'rows' -> 1 ->> 'cloud_id')::uuid < (rb -> 'rows' -> 0 ->> 'cloud_id')::uuid
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements((ra -> 'rows') || (rb -> 'rows')) e
                     WHERE (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(e) k)
                           IS DISTINCT FROM ARRAY['channel_kind', 'cloud_deal_id', 'cloud_id', 'content_hash', 'local_id', 'removed']
                        OR e ->> 'removed' <> 'false'
                        OR e ->> 'channel_kind' IS DISTINCT FROM (SELECT m.channel_kind FROM public.cloud_deal_messages m WHERE m.id = (e ->> 'cloud_id')::uuid))
    AND (SELECT string_agg(e ->> 'channel_kind', ',' ORDER BY e ->> 'local_id') FROM jsonb_array_elements((ra -> 'rows') || (rb -> 'rows')) e) = 'email,text,email'
    AND (v ->> 'ok') = 'true' AND jsonb_array_length(x_j -> 'rows') = 3
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(x_j -> 'rows') e WHERE e ->> 'removed' <> 'true'),
    jsonb_build_object('p1', ra, 'p2', rb, 'after_delete', x_j)::text);
END $c$;
CREATE FUNCTION pg_temp.c7b_list_file() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.upload(true);
  ra := pg_temp.list('IA', 'file', NULL, 1000);
  v := pg_temp.call('cloud_delete_deal', '%L::uuid, %L::uuid', pg_temp.s('A'), pg_temp.s('dA'));
  rb := pg_temp.list('IA', 'file', NULL, 1000);
  RETURN pg_temp.pass(
    jsonb_array_length(ra -> 'rows') = 4 AND ra -> 'next_after' = 'null'::jsonb
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(ra -> 'rows') e
                     WHERE (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(e) k)
                           IS DISTINCT FROM ARRAY['cloud_deal_id', 'cloud_id', 'content_hash', 'local_id', 'removed']
                        OR e ->> 'removed' <> 'false')
    AND (SELECT string_agg(e ->> 'local_id', ',' ORDER BY e ->> 'local_id') FROM jsonb_array_elements(ra -> 'rows') e) = 'fx-f1,fx-f2,fx-f3,fx-f4'
    AND (v ->> 'ok') = 'true' AND jsonb_array_length(rb -> 'rows') = 4
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(rb -> 'rows') e WHERE e ->> 'removed' <> 'true'),
    jsonb_build_object('before', ra, 'after_delete', rb)::text);
END $c$;
CREATE FUNCTION pg_temp.c_list_empty() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  v := jsonb_build_object('message', pg_temp.list('IC', 'message', NULL, 10), 'file', pg_temp.list('IC', 'file', NULL, 10));
  RETURN pg_temp.pass(v -> 'message' -> 'rows' = '[]'::jsonb AND v -> 'file' -> 'rows' = '[]'::jsonb
                      AND v -> 'message' -> 'next_after' = 'null'::jsonb AND (v -> 'message' ->> 'ok') = 'true', v::text);
END $c$;
CREATE FUNCTION pg_temp.c_list_shape() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  v := jsonb_build_object('deal', pg_temp.list('IA', 'deal', NULL, 10), 'party', pg_temp.list('IA', 'party', NULL, 10),
                          'bad', pg_temp.list('IA', 'checklist', NULL, 10));
  RETURN pg_temp.pass(jsonb_array_length(v -> 'deal' -> 'rows') = 1 AND jsonb_array_length(v -> 'party' -> 'rows') = 1
                      AND (v -> 'bad' ->> 'error') = 'invalid_input'
                      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements((v -> 'deal' -> 'rows') || (v -> 'party' -> 'rows')) e
                                       WHERE (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(e) k)
                                             IS DISTINCT FROM ARRAY['cloud_deal_id', 'cloud_id', 'content_hash', 'local_id', 'removed']), v::text);
END $c$;
CREATE FUNCTION pg_temp.c_active_gates() RETURNS text LANGUAGE plpgsql AS $c$
DECLARE v jsonb; ra jsonb; rb jsonb; x_j jsonb; before text; after text; x_n bigint;
BEGIN
  PERFORM pg_temp.computer(true);
  PERFORM pg_temp.upload(true);
  before := pg_temp.fp();
  v := jsonb_build_object(
    'messages', pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.s('dB'), jsonb_build_array(pg_temp.mrow('ag-m', 'email'))::text),
    'files', pg_temp.call('cloud_upsert_files', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.s('dB'), jsonb_build_array(pg_temp.frow('ag-f', NULL, NULL, 'too_large'))::text),
    'register', pg_temp.call('cloud_register_blob', '%L::uuid, %L::uuid, %L::text, %L::bigint, %L::text', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.h('ag-b'), '10', NULL),
    'tombstone', pg_temp.call('cloud_tombstone', '%L::uuid, %L::uuid, %L::text, %L::uuid[]', pg_temp.s('A'), pg_temp.s('IB'), 'message', ARRAY[pg_temp.f('mB')]::text));
  PERFORM pg_temp.upload(false);
  ra := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IB'), pg_temp.s('dB'), jsonb_build_array(pg_temp.mrow('ag-m2', 'email'))::text);
  x_j := pg_temp.list('IB', 'message', NULL, 10);
  after := pg_temp.fp();
  PERFORM pg_temp.upload(true);
  rb := pg_temp.call('cloud_upsert_messages', '%L::uuid, %L::uuid, %L::uuid, %L::jsonb', pg_temp.s('A'), pg_temp.s('IA'), pg_temp.s('dA'), jsonb_build_array(pg_temp.mrow('ag-ok', 'email'))::text);
  RETURN pg_temp.pass(NOT EXISTS (SELECT 1 FROM jsonb_each(v) e WHERE e.value ->> 'error' IS DISTINCT FROM 'computer_not_active')
                      AND (ra ->> 'error') = 'computer_not_active' AND before = after AND (x_j ->> 'ok') = 'true'
                      AND jsonb_array_length(x_j -> 'rows') = 1 AND (rb -> 'results' -> 0 ->> 'status') = 'applied',
                      jsonb_build_object('inactive', v, 'off_inactive', ra, 'list_inactive', x_j, 'active', rb)::text);
END $c$;

