    IF applied IS NOT TRUE THEN RAISE EXCEPTION 'MUTATION NOT APPLIED'; END IF;
    BEGIN
      res := pg_temp.c7a_messages();
      RAISE EXCEPTION 'undo-case';
    EXCEPTION WHEN OTHERS THEN
